/**
 * Get total RAM size (internal + external SRAM/PSRAM/FRAM)
 */
uint32_t guikit_hw_union_get_total_ram(const guikit_hw_config_union_t* cfg);

/**
 * Get total external RAM size
 */
uint32_t guikit_hw_union_get_external_ram(const guikit_hw_config_union_t* cfg);

/**
 * Count number of SPI expander chips
 */
