/**
 * Print configuration summary
 */
void guikit_hw_config_union_print(const guikit_hw_config_union_t* cfg);

// ============================================================================
// Inline Accessors for Type Safety
// ============================================================================

// Get RAM config from a bank (returns NULL if not RAM)
static inline const guikit_ram_config_t* guikit_bank_get_ram(const guikit_device_bank_t* bank) {
    if (GUIKIT_BANK_IS_RAM(*bank)) {
        return &bank->config.ram;
    }
    return NULL;
}

// Get SPI device config from a bank (returns NULL if not SPI device)
static inline const guikit_spi_device_config_t* guikit_bank_get_spi_device(const guikit_device_bank_t* bank) {
    if (GUIKIT_BANK_IS_SPI_DEVICE(*bank)) {
        return &bank->config.spi_device;
    }
    return NULL;
}

// Get SPI expander config from a bank (returns NULL if not expander)
static inline const guikit_spi_expander_config_t* guikit_bank_get_spi_expander(const guikit_device_bank_t* bank) {
    if (GUIKIT_BANK_IS_SPI_EXPANDER(*bank)) {
        return &bank->config.spi_expander;
    }
    return NULL;
}

// ============================================================================
// Usage Example
// ============================================================================

/**
 * Example usage of the union-based configuration:
 * 
 * guikit_hw_config_union_t config = GUIKIT_HW_UNION_ESP8266_HUGE_DEMO;
 * 
 * // Access RAM banks
 * for (int i = 0; i < config.bank_count; i++) {
 *     if (GUIKIT_BANK_IS_RAM(config.banks[i])) {
 *         const guikit_ram_config_t* ram = guikit_bank_get_ram(&config.banks[i]);
 *         printf("RAM Bank: %s, Size: %lu KB\n", config.banks[i].name, ram->size / 1024);
 *     }
 * }
 * 
 * // Access SPI expanders
 * for (int i = 0; i < config.bank_count; i++) {
 *     if (GUIKIT_BANK_IS_SPI_EXPANDER(config.banks[i])) {
 *         const guikit_spi_expander_config_t* exp = guikit_bank_get_spi_expander(&config.banks[i]);
 *         printf("Expander: %s, Type: %d\n", config.banks[i].name, exp->type);
 *     }
 * }
 * 
 * // Custom configuration
 * guikit_hw_config_union_t my_config = {0};
 * my_config.banks[0] = GUIKIT_RAM_BANK(GUIKIT_RAM_SRAM, 131072, 16, "My SRAM");
 * my_config.banks[1] = GUIKIT_SPI_EXPANDER_BANK(GUIKIT_EXPANDER_MCP23S17, 0, 255, 255, "My Expander");
 * my_config.bank_count = 2;
 */

#endif // GUIKIT_HW_CONFIG_UNION_H
